import os
from moler.config import load_config
from moler.exceptions import MolerException
from taf.config.testline.testline import TestLine
from moler.device.device import DeviceFactory
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.moler.converter import converter as moler_converter
from taf.ul.sc.util.helpers import is_dry_run

tl = None


class TestLineConfiguration(object):
    def __init__(self):
        if not is_dry_run():
            self.load_test_line_configuration()

    def load_test_line_configuration(self):
        log_dir = BuiltIn().get_variable_value("${OUTPUT DIR}")
        os.environ['LOG_DIR'] = os.path.join(log_dir, "moler")
        moler_config = BuiltIn().get_variable_value("${moler_config}", False)

        if self._is_defined_tl_robot_variable():
            self._set_tl_configuration_as_global()
            self._load_moler_configuration_based_on_tl_variable(taf_tl=tl, additional_config=moler_config)
        elif moler_config:
            moler_config['LOGGER']['PATH'] = os.environ['LOG_DIR']
            load_config(config=moler_config, config_type='dict')

    def _load_moler_configuration_based_on_tl_variable(self, taf_tl=tl, additional_config={}):

        logger_params = {
            'PATH': os.environ['LOG_DIR'],
            'DEBUG_LEVEL': "INFO"
        }

        mtl = moler_converter()
        mtl.prepare_configuration(taf_tl=taf_tl, create_at_startup=False, logger_params=logger_params)

        # mtl.configure_logger()  # eg change MODE

        if additional_config:
            for device_name in additional_config:
                mtl.add_device_to_existing_configuration(device=additional_config[device_name],
                                                         exception_if_exist=False)
        # Its WA. Need to remove after fix in moler
        try:
            mtl.load_configuration()
        except MolerException:
            pass

    def _is_defined_tl_robot_variable(self):
        return BuiltIn().get_variable_value("${tl}", False)

    def _set_tl_configuration_as_global(self, taf_tl=None):
        global tl
        if isinstance(taf_tl, TestLine):
            tl = taf_tl
        else:
            tl = BuiltIn().get_variable_value("${tl}")

        return tl

    def connect_to_all_moler_devices(self):
        DeviceFactory.create_all_devices()
